	private void assertOrderedValues(SailDatasetTripleTermSource source, LmdbNativeEvaluationStrategy strategy) {
		List<Value> expected = List.of(repository.getValueFactory().createLiteral(VALUES[0]),
				repository.getValueFactory().createLiteral(VALUES[1]),
				repository.getValueFactory().createLiteral(VALUES[2]));
		assertThat(drain(strategy.genericOnlyView().precompile(orderedRoot(bOnly(), source))).stream()
				.map(row -> row.getValue("n"))
				.toList()).containsExactlyElementsOf(expected);
		assertThat(drain(strategy.precompile(orderedRoot(bOnly(), source))).stream()
				.map(row -> row.getValue("n"))
				.toList()).containsExactlyElementsOf(expected);
	}

	private List<Value> lexicalValues() {
		List<Value> values = new ArrayList<>();
		for (int copy = 0; copy < 2; copy++) {
			for (double value : VALUES) {
				values.add(repository.getValueFactory().createLiteral(value));
			}
		}
		return values;
	}

	private List<BindingSet> hand() {
		List<BindingSet> result = new ArrayList<>();
		ValueFactory vf = repository.getValueFactory();
		for (int copy = 0; copy < 2; copy++) {
			for (int index = 0; index < VALUES.length; index++) {
				MapBindingSet row = new MapBindingSet();
				row.addBinding("a", vf.createLiteral("anchor"));
				row.addBinding("b", orderedSubjects.get(index));
				row.addBinding("n", vf.createLiteral(VALUES[index]));
				row.addBinding("c", vf.createLiteral("ab"));
				row.addBinding("u", vf.createLiteral("1", XSD.INTEGER));
				result.add(row);
			}
		}
		return result;
	}

	private TupleExpr orderedRoot(String query, SailDatasetTripleTermSource source) {
		assertThat(store.getQueryExecutionPolicy().experimentalQueryOptimizations()).isTrue();
		assertThat(source.getComparator()).isNotNull();
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		root.setRuntimeTelemetryEnabled(true);
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				if (repository.getValueFactory().createIRI(EX, "b").equals(pattern.getPredicateVar().getValue())) {
					assertThat(pattern.getSupportedOrders(source)).contains(pattern.getSubjectVar());
					pattern.setOrder(pattern.getSubjectVar());
				}
			}
		});
		return root;
	}

	private SailDatasetTripleTermSource source(SailDataset dataset) {
		assertThat(dataset).isInstanceOf(NativeLmdbQuerySource.class);
		return new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
	}

	private LmdbNativeEvaluationStrategy strategy(SailDatasetTripleTermSource source) {
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(source, null, null, 0L,
				new EvaluationStatistics(), false);
		strategy.setQueryExecutionPolicy(store.getQueryExecutionPolicy());
		assertThat(strategy.getQueryExecutionPolicy()).isSameAs(store.getQueryExecutionPolicy());
		return strategy;
	}

	private static QueryEvaluationContext context() {
		return new QueryEvaluationContext.Minimal((Dataset) null);
	}

	private static List<BindingSet> drain(QueryEvaluationStep step) {
		try (CloseableIteration<BindingSet> result = step.evaluate(EmptyBindingSet.getInstance())) {
			return QueryResults.asList(result);
		}
	}

	private static String bOnly() {
		return "SELECT ?b ?n WHERE { ?b <" + EX + "b> ?n }";
	}

	private static String query() {
		return "SELECT ?a ?b ?n ?c ?u WHERE { <" + EX + "anchor> <" + EX + "a> ?a . "
				+ "{ SELECT (CONCAT(\"a\", \"b\") AS ?c) ?u WHERE { VALUES ?u { 1 1 } } } "
				+ "?b <" + EX + "b> ?n }";
	}
